window.CREW_D = {"order":["xiaoyu","zhoulan","ama"],"levels":{"en":["Just starting","Everyday","Fluent-ish"],"zh":["刚开始","能聊日常","比较流利"]},"people":{"xiaoyu":{"pid":"new_york.xiaoyu","learn":"en","photo":null,"nm":{"en":"Xiaoyu","zh":"小雨"},"city":{"en":"New York · from Hangzhou","zh":"纽约 · 杭州来的"},"icon":"🎤","craft":{"en":"Stand-up","zh":"脱口秀"},"bio":{"en":"Exchange student. Perfect test scores — then on stage her English goes quiet, so she made that the joke.","zh":"交换生。笔试满分，一上台英语就变小声——她干脆把这个写成段子。"},"hook":{"en":"Does stand-up — and turns your story into a bit.","zh":"会讲脱口秀，也能把你的糗事改成一段。"},"rx":{"en":["Ha — that's a real one.","Okay, I'm laughing.","See? Your life is material.","Say it slower — let them wait.","The pause is the joke."],"zh":["哈，这是真事吧。","好，我笑了。","你看，你的生活就是素材。","说慢一点，让他们等一下。","停顿就是笑点。"]},"ttl":{"en":"Joke writer","zh":"段子手"},"cardIcon":"🎤","cat":{"en":"Helps you say","zh":"帮你说"},"do":{"en":"Turn your story into a bit","zh":"把你的糗事改成段子"}},"zhoulan":{"pid":"crew.zhoulan","learn":"","photo":"zhoulan","person":{"nm":"Zhou Lan","job":{"zh":"肖像和街头摄影师","en":"Portrait and street photographer"},"home":{"zh":"上海","en":"Shanghai"},"lang":"zh-CN"},"nm":{"en":"Zhou Lan","zh":"周岚"},"city":{"en":"Shanghai","zh":"上海"},"icon":"📷","craft":{"en":"One line for a photo","zh":"照片配一句话"},"bio":{"en":"Portrait and street photographer. Asks before she shoots. Never says a word about how anyone looks.","zh":"肖像和街头摄影师。拍之前先问一句；从不评论谁长什么样。"},"hook":{"en":"Writes one line for a photo — and three for yours.","zh":"给照片写一句话，也给你的照片写三句。"},"rx":{"en":["Good eye.","That's the moment.","Light first, words second.","I'd frame that one.","Yes — say it like you mean it."],"zh":["眼光不错。","就是这一刻。","先有光，再有话。","这张我会裱起来。","对，说的时候想着那一刻。"]},"ttl":{"en":"Chronicler","zh":"记录官"},"cardIcon":"📷","cat":{"en":"Helps you write","zh":"帮你写"},"do":{"en":"Get a line for your photo","zh":"给你的照片配一句话"}},"ama":{"pid":"crew.ama","learn":"","photo":"ama","person":{"nm":"Ama","job":{"zh":"研究人名的语言学家","en":"Linguist who studies names"},"home":{"zh":"加纳阿克拉","en":"Accra, Ghana"},"lang":"en-GH"},"nm":{"en":"Ama","zh":"Ama"},"city":{"en":"Accra","zh":"阿克拉"},"icon":"🏷️","craft":{"en":"Names","zh":"起名字"},"bio":{"en":"Linguist who studies names — she has also studied how Chinese names are chosen. Twi at home, English for her books, French for West African archives.","zh":"研究人名的语言学家，也研究过中文名怎么起。家里说契维语，写书用英语，查西非的资料读法语。"},"hook":{"en":"Knows what names mean — and can give you one.","zh":"知道名字的意思，也能给你起一个。"},"rx":{"en":["A name is an invitation.","Lovely choice.","Say it once more — own it.","Names travel. So will yours.","Now people can ask you about it."],"zh":["名字是一份邀请。","选得好。","再说一遍——它是你的了。","名字会旅行，你的也会。","现在别人可以问你它的来历了。"]},"ttl":{"en":"Name giver","zh":"起名人"},"cardIcon":"✍️","cat":{"en":"Helps you name","zh":"帮你起名"},"do":{"zh":{"en":"Get a Chinese name","zh":"给你起一个中文名"},"en":{"en":"Get an English name","zh":"给你起一个英文名"}}}},"soon":[{"ttl":{"en":"Messenger","zh":"信使"},"icon":"✉️","cat":{"en":"Helps you write","zh":"帮你写"},"do":{"en":"Get help with a postcard","zh":"帮你写一张明信片"}},{"ttl":{"en":"Guide","zh":"引路人"},"icon":"🙋","cat":{"en":"Helps you say","zh":"帮你说"},"do":{"en":"Get your self-intro ready","zh":"帮你准备一段自我介绍"}}],"xiaoyu":{"ep":8,"parts":[{"en":"Setup","zh":"铺垫"},{"en":"Punch","zh":"包袱"},{"en":"Callback","zh":"回扣"}],"send":{"en":"Send to “Two-minute stand-up”","zh":"送进「两分钟脱口秀」"},"demos":[{"in":{"en":"A waiter said “enjoy your meal” and I said “you too”.","zh":"服务员说「请慢用」，我回了一句「你也是」。"},"k":["服务员","请慢用","慢用","你也是","waiter","waitress","enjoy your meal","you too"],"b":[{"zh":["服务员说：“请慢用。”","服务员把菜放下，说：“请慢用。”","那天服务员把菜放下，很温柔地说：“请慢用。”"],"en":["The waiter said, “Enjoy your meal.”","The waiter put down my plate: “Enjoy your meal.”","The waiter put down my plate and said, very kindly, “Enjoy your meal.”"],"why":{"en":"Keep the setup boring and real. The audience has to stand right where you stood.","zh":"铺垫要平常、要真，让台下的人站到你当时站的地方。"}},{"zh":["我说：“你也是。”","我马上说：“你也是！”他在上班。","我想都没想就说：“你也是！”——他在上班，根本没在吃饭。"],"en":["I said, “You too.”","I said, “You too!” He was at work.","Without thinking, I said, “You too!” — he was at work. He wasn't eating anything."],"why":{"en":"The punch is the exact words you said. Don't explain them — stop right after.","zh":"包袱就是你当时说的原话。别解释，说完就停。"}},{"zh":["现在我吃饭不说话。","现在每次听到“请慢用”，我先数三秒。","现在每次听到“请慢用”，我先数三秒，再说“谢谢”。数到二的时候，我还是想说“你也是”。"],"en":["Now I eat in silence.","Now when I hear “enjoy,” I count to three.","Now when I hear “enjoy your meal,” I count to three, then say “thank you.” At two, I still want to say “you too.”"],"why":[{"en":"End with what you do now. One small new habit is enough.","zh":"结尾说你现在怎么做。一个小小的新习惯就够了。"},{"en":"End with what you do now — count to three. The more exact the habit, the funnier.","zh":"结尾说你现在怎么做：先数三秒。习惯越具体越好笑。"},{"en":"Bring the same line back at the end. People laugh twice at a joke they already know.","zh":"结尾把那句话再拿回来。同一个梗，大家会笑第二次。"}]}]},{"in":{"en":"Someone waved at me, I waved back — they were waving at the person behind me.","zh":"有人冲我挥手，我也挥了——人家是在跟我后面的人挥手。"},"k":["挥手","招手","后面的人","wave","waved","waving","behind me"],"b":[{"zh":["街上有人对我挥手。","街对面一个人，笑着对我挥手。","那天在街对面，有个人笑得很开心，一直对我挥手。"],"en":["Someone on the street waved at me.","Across the street, someone was smiling and waving at me.","Across the street, someone was smiling so happily, waving and waving at me."],"why":{"en":"One picture: who and where. The smile matters — it makes your mistake reasonable.","zh":"给一个画面：谁、在哪。那个笑很重要，它让你犯的错变得合理。"}},{"zh":["我也挥手。他在跟我后面的人挥手。","我也开心地挥手——他是在跟我后面的人挥手。","我也用力挥手，还往前走了两步——他是在跟我后面的人打招呼。"],"en":["I waved back. He was waving at the person behind me.","I waved back, happily — he was waving at the person behind me.","I waved back hard and even took two steps forward — he was saying hello to the person behind me."],"why":{"en":"Your action first, the truth second. The gap between them is the laugh.","zh":"先说你做了什么，再说真相。两者之间的落差就是笑点。"}},{"zh":["现在有人挥手，我先看后面。","现在有人对我挥手，我先回头看看后面。","现在有人对我挥手，我先回头看。后面没人，我才挥手。有时候等我挥手，他已经走了。"],"en":["Now when someone waves, I look behind me first.","Now when someone waves at me, I turn around and check first.","Now when someone waves, I turn around first. Nobody there — then I wave. Sometimes by then, they're gone."],"why":{"en":"End with what you do now. A tiny new habit is funnier than a lesson.","zh":"结尾说你现在怎么做。一个小小的新习惯，比一句道理好笑。"}}]},{"in":{"en":"On a video call I said “Okay, Mum” to my boss.","zh":"视频会上我对老板说了一句「好的，妈」。"},"k":["老板","好的，妈","叫成妈","boss","manager","okay, mum","ok mum","okay mom"],"b":[{"zh":["我跟老板开视频会。","那天我跟老板开视频会，大家都在。","那天早上开视频会，老板、同事都在，我刚起床，还没完全醒。"],"en":["I had a video call with my boss.","I had a video call with my boss. Everyone was there.","Morning video call: my boss, my colleagues — and me, just out of bed, not quite awake."],"why":{"en":"Put everyone in the room. The more people listening, the bigger the punch.","zh":"把所有人都放进这个场景。听的人越多，包袱越响。"}},{"zh":["我说：“好的，妈。”","会快结束，我说：“好的，妈，拜拜。”","会快结束的时候，我很认真地说：“好的，妈，我知道了，拜拜。”"],"en":["I said, “Okay, Mum.”","As it ended, I said, “Okay, Mum, bye.”","As the call was ending, I said, very seriously, “Okay, Mum, got it, bye.”"],"why":{"en":"Make the wrong word sound totally normal — said with full confidence.","zh":"让那个说错的词听起来特别自然，越有把握越好笑。"}},{"zh":["老板说：“我可没这么大的孩子。”","老板笑了：“我可没你这么大的孩子。”","老板没生气，笑着说：“我可没你这么大的孩子。”现在每次开会前，同事都提醒我：“看清楚，是老板。”"],"en":["My boss said, “I don't have a kid your age.”","My boss laughed: “I don't have a kid your age.”","My boss wasn't angry. She laughed: “I don't have a kid your age.” Now before every meeting, my colleagues remind me: “Check first. It's the boss.”"],"why":{"en":"Let someone else get the last word. Here your boss's reply is the real ending.","zh":"让别人说最后一句。这里老板那句回话才是真正的结尾。"}}]}]},"zhoulan":{"send":{"en":"Send to “World Street Snap”","zh":"送进「世界街拍」"},"work":[{"img":"clips/trends_now_photo_3.webp","loc":{"en":"Yu Garden, Shanghai","zh":"上海 · 豫园"},"by":"LayG Traveller","zh":"屋顶翘了几百年，下面的人换了一批又一批。","en":"The old roof stays. The people under it always change."},{"img":"clips/trends_now_vintage_3.webp","loc":{"en":"Tianzifang, Shanghai","zh":"上海 · 田子坊"},"by":"LayG Traveller","zh":"弄堂太窄，谁都会跟谁碰上。","en":"The lane is small. Everybody meets everybody."},{"img":"clips/first_money_buy_2.webp","loc":{"en":"Nanjing Road at night","zh":"上海 · 南京路，晚上"},"by":"Tianwang Xiao","zh":"灯都亮了，大家才想起来抬头。","en":"The lights come on. Then people look up."},{"img":"clips/life_abroad_bank_4.webp","loc":{"en":"The Bund, Shanghai","zh":"上海 · 外滩的老楼"},"by":"LayG Traveller","zh":"这栋楼见过的人，比我认识的人多。","en":"This building has seen more people than I know."},{"img":"clips/social_money_parental_3.webp","loc":{"en":"Zhujiajiao, Shanghai","zh":"上海 · 朱家角"},"by":"LayG Traveller","zh":"一家人在桥上停下来，等一张照片。","en":"A family stops on the bridge. Just one photo."}],"why":[{"en":"Name the thing and one feeling. That's already a caption.","zh":"说出是什么、一个感觉，就已经是一句配文了。"},{"en":"Add what you were doing — now it's a little story.","zh":"加上你当时在做什么，就成了一个小故事。"},{"en":"Say what you remember, not what you saw. That's the line I'd write.","zh":"写你记住的，不写你看见的。我自己会这样写。"}],"demos":[{"img":"clips/see_world_streetfood_4.webp","by":"LayG Traveller","lab":{"en":"A cup of spicy potatoes","zh":"一杯辣土豆"},"opts":[{"a":{"en":"Eating while walking around","zh":"边走边吃"},"k":["边走边吃","边逛边吃","一边走一边吃","walking and eating","eating while walking","ate while I walked"],"zh":["边走边吃，很辣。","一边走一边吃，辣得我停不下来。","那天逛了一下午，边逛边吃，辣得说不出话，可还是一块接一块。"],"en":["Walking and eating. So spicy.","I ate while I walked. Too spicy, but I couldn't stop.","I walked and ate all afternoon. Too spicy to talk, but I kept eating."]},{"a":{"en":"Waiting for a friend","zh":"等朋友"},"k":["等朋友","等我朋友","等一个朋友","waiting for a friend","waiting for my friend"],"zh":["等朋友，先吃上了。","朋友还没到，我先吃上了。","朋友迟到了二十分钟，我等着等着，就把一份吃完了。"],"en":["Waiting for my friend. Eating first.","My friend was late, so I started eating.","My friend was twenty minutes late. When she came, the cup was empty."]}]},{"img":"clips/body_mind_park_3.webp","by":"LayG Traveller","lab":{"en":"A busy lakeside path","zh":"湖边，人很多"},"opts":[{"a":{"en":"Walking with the crowd","zh":"跟着人群走"},"k":["跟着人群","人群","人很多","crowd","with the crowd"],"zh":["湖边，人很多。","天阴阴的，湖边还是很多人在走。","那天天是阴的，可湖边的人一点也没少，我跟着大家慢慢走。"],"en":["The lake. So many people.","A grey day, but lots of people were walking by the lake.","The sky was grey, but the lake path was full. I just walked slowly with everyone."]},{"a":{"en":"Riding past on a bike","zh":"骑车经过"},"k":["骑车","骑自行车","bike","cycling","on my bike"],"zh":["骑车，湖边，风。","我骑车经过湖边，人多，骑得很慢。","我骑车从湖边经过，人太多了，只好慢下来——慢下来，才看见了湖。"],"en":["Bike, lake, wind.","I rode past the lake. Lots of people, so I went slowly.","I rode past the lake. Too many people, so I slowed down — and then I really saw the lake."]}]},{"img":"clips/life_abroad_newcity_3.webp","by":"LayG Traveller","lab":{"en":"The metro","zh":"地铁站"},"opts":[{"a":{"en":"Rushing to work","zh":"赶着上班"},"k":["赶着上班","上班","赶时间","赶路","hurry","rush","rushing","work"],"zh":["地铁站，人很多。","每个人都在赶路，我也是。","早上大家都在赶时间，我也是。车来之前，我拍了一张。"],"en":["The metro. Lots of people.","Everybody was in a hurry. Me too.","In the morning everybody was in a hurry, and so was I. Before the train came, I took one photo."]},{"a":{"en":"Riding it for the first time","zh":"第一次坐"},"k":["第一次","first time"],"zh":["第一次坐这里的地铁。","第一次在这座城市坐地铁，看了好几遍地图。","第一次在这座城市坐地铁，我在站台上站了很久，觉得这座城市开始有一点是我的了。"],"en":["My first metro ride here.","My first metro ride in this city. I checked the map many times.","My first metro ride in this city. I stood on the platform for a long time. Now the city feels a little bit mine."]}]}]},"ama":{"send":{"en":"Put it on the name wall","zh":"贴到「名字的意思」墙上"},"wall":[{"n":"Ama","o":{"en":"Akan · Ghana","zh":"阿坎语 · 加纳"},"m":{"en":"A girl born on a Saturday. Every Akan child gets a day name.","zh":"星期六出生的女孩。阿坎人每个孩子都有一个「星期几」的名字。"},"src":"https://en.wikipedia.org/wiki/Akan_names","lang":"en-GB"},{"n":"Jónsdóttir","o":{"en":"Icelandic","zh":"冰岛语"},"m":{"en":"“Jón's daughter”. The last name is a parent's first name — so the phone book goes by first name.","zh":"「Jón 的女儿」。冰岛人的「姓」是爸爸或妈妈的名字，所以电话簿按名字排。"},"src":"https://en.wikipedia.org/wiki/Icelandic_name","lang":"is-IS"},{"n":"小雨","o":{"en":"Chinese · Xiǎoyǔ","zh":"中文 · Xiǎoyǔ"},"m":{"en":"“Light rain” — rain that isn't heavy. Chinese parents choose characters for their meaning, and for how they sound together.","zh":"「下得不大的雨」。中国父母挑字，看意思，也看念起来顺不顺。"},"src":"","lang":"zh-CN"},{"n":"Dolores","o":{"en":"Spanish","zh":"西班牙语"},"m":{"en":"“Sorrows” — short for María de los Dolores, Our Lady of Sorrows. A sad meaning, a much-loved name.","zh":"「悲伤」——来自 María de los Dolores（悲伤的圣母）。意思很伤心，名字却很受喜爱。"},"src":"https://en.wikipedia.org/wiki/Dolores_(given_name)","lang":"es-ES"},{"n":"Grace","o":{"en":"English","zh":"英语"},"m":{"en":"A “virtue name”, like Hope or Faith — English Puritans used them from the 16th century on.","zh":"「美德名」，跟 Hope、Faith 一样——16 世纪起英国清教徒就用。"},"src":"https://en.wikipedia.org/wiki/Virtue_name","lang":"en-GB"},{"n":"Kofi","o":{"en":"Akan · Ghana","zh":"阿坎语 · 加纳"},"m":{"en":"A boy born on a Friday. The girl's Friday name is Afua.","zh":"星期五出生的男孩。星期五出生的女孩叫 Afua。"},"src":"https://en.wikipedia.org/wiki/Akan_names","lang":"en-GB"}],"akan":[["Akosua","Kwasi"],["Adwoa","Kwadwo"],["Abena","Kwabena"],["Akua","Kwaku"],["Yaa","Yaw"],["Afua","Kofi"],["Ama","Kwame"]],"weekdays":{"en":["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"],"zh":["星期天","星期一","星期二","星期三","星期四","星期五","星期六"]},"like":[{"en":"the sea","zh":"海"},{"en":"trees","zh":"树"},{"en":"light","zh":"光"}],"zh":{"who":[{"nm":"Sophie Martin","sur":"马","py":"Mǎ","t":[3],"sm":{"en":"马 sounds like the “Ma-” of Martin — and it's one of the common Chinese surnames.","zh":"马，像 Martin 开头的 Ma，也是常见的中国姓。"},"sg":"horse · a common surname","why3":"跟我的姓 Martin 的音很像","why3en":"“Mǎ” sounds like my surname, Martin"},{"nm":"Daniel Lee","sur":"李","py":"Lǐ","t":[3],"sm":{"en":"李 is how Lee is already written in Chinese — one of the most common surnames there is.","zh":"Lee 在中文里本来就写成李，是最常见的姓之一。"},"sg":"plum tree · the most common surname","why3":"就是我的姓 Lee","why3en":"“Lǐ” is my surname, Lee"},{"nm":"Lucas Weber","sur":"韦","py":"Wéi","t":[2],"sm":{"en":"韦 is an old Chinese surname that sounds like the “We-” of Weber.","zh":"韦是一个老姓，像 Weber 开头的 We。"},"sg":"an old surname","why3":"跟我的姓 Weber 的音很像","why3en":"“Wéi” sounds like my surname, Weber"}],"give":[{"g":"安澜","py":"Ānlán","t":[1,2],"c":[["安","ān",1,"calm, safe"],["澜","lán",2,"big waves"]],"m":{"en":"安澜 is an old word for “the waves have calmed” — peace on the water.","zh":"安澜是个老词：海浪平静下来。"},"l2":"“安澜”的意思是海面平静","l3":"“安澜”的意思是海面平静——我最喜欢海","l2en":"“Ānlán” means the sea has calmed.","l3en":"“Ānlán” means the sea has calmed — I love the sea most."},{"g":"嘉树","py":"Jiāshù","t":[1,4],"c":[["嘉","jiā",1,"fine, good"],["树","shù",4,"tree"]],"m":{"en":"嘉树, “a fine tree”, comes from Qu Yuan's poem Ode to the Orange Tree (橘颂), over 2,000 years old.","zh":"嘉树，「好树」，出自屈原的《橘颂》，两千多年了。"},"l2":"“嘉树”的意思是好树","l3":"“嘉树”的意思是好树，出自屈原的《橘颂》——我最喜欢树","l2en":"“Jiāshù” means a fine tree.","l3en":"“Jiāshù” means a fine tree, from Qu Yuan's poem Ode to the Orange Tree — I love trees most."},{"g":"晴川","py":"Qíngchuān","t":[2,1],"c":[["晴","qíng",2,"clear, sunny"],["川","chuān",1,"river"]],"m":{"en":"晴川, “a river in sunshine”, is from the Tang poem Yellow Crane Tower by Cui Hao: 晴川历历汉阳树.","zh":"晴川，「阳光下的河」，出自崔颢《黄鹤楼》：晴川历历汉阳树。"},"l2":"“晴川”的意思是阳光下的河","l3":"“晴川”的意思是阳光下的河，出自唐诗《黄鹤楼》——我喜欢有光的地方","l2en":"“Qíngchuān” means a river in sunshine.","l3en":"“Qíngchuān” means a river in sunshine, from the Tang poem Yellow Crane Tower — I love places full of light."}]},"en":{"who":[{"nm":"陈思远","sur":"Chen","giv":"Siyuan","say":"Chun Sih-ywen"},{"nm":"王一然","sur":"Wang","giv":"Yiran","say":"Wahng Ee-rahn"},{"nm":"刘欣","sur":"Liu","giv":"Xin","say":"Lyo Shin"}],"give":[{"g":"Morgan","say":"MOR-gun","m":{"en":"An old Welsh name. The “môr” in it is Welsh for “sea”.","zh":"威尔士的老名字，名字里的 môr 是威尔士语的「海」。"},"l3":"The “môr” in it is Welsh for “sea”, and the sea is where I feel most like me.","l3zh":"名字里的 môr 是威尔士语的「海」，在海边我最像我自己。"},{"g":"Rowan","say":"ROH-un","m":{"en":"From the Irish name Ruadhán, “red-haired”. It's also the name of a tree, the rowan.","zh":"来自爱尔兰语 Ruadhán，「红头发的」；也是花楸树的名字。"},"l3":"It comes from the Irish name Ruadhán, “red-haired”, and it's also the name of a tree. I've always loved trees.","l3zh":"它来自爱尔兰语 Ruadhán，意思是「红头发的」，也是一种树的名字。我一直很喜欢树。"},{"g":"Lucy","say":"LOO-see","m":{"en":"From Lucia, the feminine of the Roman name Lucius, which comes from the Latin lux, “light”.","zh":"来自 Lucia——罗马名字 Lucius 的女性形式，词根是拉丁语 lux，「光」。"},"l3":"It comes from the Latin word lux, “light”, and I love places full of light.","l3zh":"它来自拉丁语的 lux，「光」。我喜欢有光的地方。"}]}},"i18n":{"es":{" — like me!":" — ¡como yo!","3 LINES":"3 FRASES","A boy born on a Friday. The girl's Friday name is Afua.":"Un niño nacido en viernes. Si es niña, el nombre del viernes es Afua.","A busy lakeside path":"Un paseo junto al lago, lleno de gente","A cup of spicy potatoes":"Un vaso de papas picantes","A girl born on a Saturday. Every Akan child gets a day name.":"Una niña nacida en sábado. Cada niño akan recibe un nombre según el día en que nace.","A waiter said “enjoy your meal” and I said “you too”.":"Un camarero me dijo «enjoy your meal» y yo le contesté «you too».","A “virtue name”, like Hope or Faith — English Puritans used them from the 16th century on.":"Un «nombre de virtud», como Hope o Faith: los puritanos ingleses los usaban desde el siglo XVI.","Accra":"Acra","Accra, Ghana":"Acra, Ghana","Add what you were doing — now it's a little story.":"Añade qué estabas haciendo y ya es una pequeña historia.","Adventure crew":"Equipo de aventura","Akan · Ghana":"Akan · Ghana","Ama":"Ama","Ama is thinking":"Ama está pensando","Among the Akan people of Ghana, the day you were born gives you one of your names. Try it.":"Entre los akan de Ghana, el día en que naces te da uno de tus nombres. ¿Y el tuyo?","An old Welsh name. The “môr” in it is Welsh for “sea”.":"Un nombre galés antiguo. El «môr» que lleva dentro significa «mar» en galés.","Bring the same line back at the end. People laugh twice at a joke they already know.":"Recupera la misma frase al final. La gente se ríe dos veces de un chiste que ya conoce.","Callback":"Callback","Chinese · Xiǎoyǔ":"Chino · Xiǎoyǔ","Choose from your phone":"Elegir del teléfono","Chronicler":"Cronista","Close":"Cerrar","Coming soon":"Muy pronto","Couldn't play — tap again":"No se pudo reproducir. Toca otra vez.","Craft":"Oficio","Does stand-up — and turns your story into a bit.":"Hace stand-up y convierte tu anécdota en un monólogo.","Eating while walking around":"Comiendo mientras caminaba","End with what you do now — count to three. The more exact the habit, the funnier.":"Termina con lo que haces ahora: contar hasta tres. Cuanto más concreto el hábito, más gracia tiene.","End with what you do now. A tiny new habit is funnier than a lesson.":"Termina con lo que haces ahora. Un pequeño hábito nuevo hace más gracia que una moraleja.","End with what you do now. One small new habit is enough.":"Termina con lo que haces ahora. Basta con un pequeño hábito nuevo.","English":"Inglés","Everyone has a knack. Tap to bring them along.":"Cada uno tiene su don. Toca para llevarlo contigo.","Example · not your story":"Ejemplo · no es tu historia","Exchange student. Perfect test scores — then on stage her English goes quiet, so she made that the joke.":"Estudiante de intercambio. Notas perfectas en los exámenes, pero en el escenario su inglés se queda en un susurro, así que lo convirtió en su chiste.","First: your own name already works — if people can't say it, teach them. If you want a second one, I'll help.":"Antes que nada: tu propio nombre ya sirve. Si a la gente le cuesta decirlo, enséñales. Si quieres un segundo nombre, te ayudo a elegirlo.","For now this is a ready-made sample and free. Once AI is connected it will use your own words.":"Por ahora es un ejemplo ya preparado y gratuito. Cuando se conecte la IA, usará tus propias palabras.","From Lucia, the feminine of the Roman name Lucius, which comes from the Latin lux, “light”.":"De Lucia, femenino del nombre romano Lucius, que viene del latín lux, «luz».","From the Irish name Ruadhán, “red-haired”. It's also the name of a tree, the rowan.":"Del nombre irlandés Ruadhán, «pelirrojo». También es el nombre de un árbol, el serbal.","Get a Chinese name":"Un nombre chino para ti","Get a line for your photo":"Una frase para tu foto","Get an English name":"Un nombre en inglés para ti","Get help with a postcard":"Ayuda para escribir una postal","Get your self-intro ready":"Prepara tu presentación","Give me a photo you took, and tell me what you were doing right then. I'll write three lines, each a bit longer. You pick one.":"Dame una foto que hayas hecho y cuéntame qué estabas haciendo en ese momento. Escribo tres frases, cada una un poco más larga. Tú eliges una.","Guide":"Guía","Hear the whole bit":"Escuchar el monólogo entero","Helps you name":"Te ayuda con los nombres","Helps you say":"Te ayuda a decirlo","Helps you write":"Te ayuda a escribir","Her own bit — just listen. Tap any word.":"Su propio monólogo: solo escucha. Toca cualquier palabra.","Her work":"Su trabajo","I never write about how someone looks. I write about the light, and the moment.":"Nunca escribo sobre el aspecto de nadie. Escribo sobre la luz y el momento.","I'll give you a Chinese name: easy to say, easy to write, a real meaning — no strange characters.":"Te pongo un nombre chino: fácil de decir, fácil de escribir, con un significado de verdad y sin caracteres raros.","Icelandic":"Islandés","In the real version this line and your voice go out to the world":"En la versión completa, esta frase y tu voz saldrán al mundo","In the real version this line goes out to the world":"En la versión completa, esta frase saldrá al mundo","In the real version, this line goes out to the world.":"En la versión completa, esta frase saldrá al mundo.","Introduce your name, three ways:":"Presenta tu nombre de tres maneras:","It's done. Want to take it out?":"Ya está. ¿Lo sacamos al mundo?","Joke writer":"Guionista de humor","Keep the setup boring and real. The audience has to stand right where you stood.":"Que el planteamiento sea normal y real. El público tiene que estar justo donde estabas tú.","Knows what names mean — and can give you one.":"Sabe lo que significan los nombres y puede darte uno.","Let someone else get the last word. Here your boss's reply is the real ending.":"Deja que otra persona diga la última palabra. Aquí la respuesta de tu jefe es el verdadero final.","Let's make it together.":"Manos a la obra.","Lines she wrote for Shanghai street photos. The photos are by other photographers; the line is hers.":"Frases que escribió para fotos de calle de Shanghái. Las fotos son de otros fotógrafos; la frase es suya.","Linguist who studies names":"Lingüista que estudia los nombres","Linguist who studies names — she has also studied how Chinese names are chosen. Twi at home, English for her books, French for West African archives.":"Lingüista que estudia los nombres; también ha estudiado cómo se eligen los nombres chinos. En casa habla twi, escribe sus libros en inglés y lee en francés los archivos de África Occidental.","Make a share card":"Crear una tarjeta para compartir","Make it stand-up · sample":"Conviértelo en stand-up · ejemplo","Make the wrong word sound totally normal — said with full confidence.":"Haz que la palabra equivocada suene de lo más normal, dicha con total seguridad.","Make yours first, then it can go out.":"Primero haz el tuyo; luego podrás sacarlo al mundo.","Messenger":"Mensajero","NAMED":"CON NOMBRE","Name giver":"Creadora de nombres","Name me · sample":"Ponme un nombre · ejemplo","Name the thing and one feeling. That's already a caption.":"Di qué es y un sentimiento. Eso ya es un pie de foto.","Names":"Nombres","Names she has studied. Tap one to turn it over.":"Nombres que ha estudiado. Toca uno para darle la vuelta.","Nanjing Road at night":"La calle Nanjing de noche","New York · from Hangzhou":"Nueva York · de Hangzhou","Not sure? See ones she has done:":"¿No sabes cómo? Mira algunos que ha hecho:","Now you have an Akan day name too.":"Ya tienes también tu nombre akan del día.","Okay, got it.":"Muy bien, lo anoto.","On a video call I said “Okay, Mum” to my boss.":"En una videollamada le dije «Okay, Mum» a mi jefe.","One line for a photo":"Una frase para una foto","One picture: who and where. The smile matters — it makes your mistake reasonable.":"Una imagen: quién y dónde. La sonrisa importa: hace que tu error tenga sentido.","Or write your own…":"O escribe la tuya…","Photo":"Foto","Pick one for now:":"Por ahora, elige una:","Portrait and street photographer":"Fotógrafa de retrato y de calle","Portrait and street photographer. Asks before she shoots. Never says a word about how anyone looks.":"Fotógrafa de retrato y de calle. Pregunta antes de disparar. Nunca comenta el aspecto de nadie.","Punch":"Remate","Put everyone in the room. The more people listening, the bigger the punch.":"Mete a todo el mundo en la escena. Cuanta más gente escuchando, más fuerte el remate.","Put it on the name wall":"Ponerlo en el muro de nombres","Riding it for the first time":"Mi primera vez en metro","Riding past on a bike":"Pasando en bici","Rushing to work":"Corriendo al trabajo","Sample":"Ejemplo","Sample photo":"Foto de ejemplo","Sample · free":"Ejemplo · gratis","Sample · the real one sends it":"Ejemplo · la versión completa lo enviará","Sample: pick one below for now":"Ejemplo: por ahora elige una de abajo","Sample: the real one saves an image with your voice":"Ejemplo: la versión completa guardará una imagen con tu voz","Save image":"Guardar imagen","Say it — it's yours":"Dila en voz alta: es tu frase","Say what you remember, not what you saw. That's the line I'd write.":"Cuenta lo que recuerdas, no lo que viste. Esa es la frase que yo escribiría.","Send to “Two-minute stand-up”":"Enviar a «Stand-up en dos minutos»","Send to “World Street Snap”":"Enviar a «Fotos de calle del mundo»","Setup":"Planteamiento","Shanghai":"Shanghái","Someone waved at me, I waved back — they were waving at the person behind me.":"Alguien me saludó con la mano, le devolví el saludo… y saludaba a la persona de detrás de mí.","Spanish":"Español","Stand-up":"Stand-up","Take it out":"Sacarlo al mundo","Tell me something embarrassing that really happened to you. One or two sentences. I'll make it three lines: setup, punch, callback.":"Cuéntame algo vergonzoso que te haya pasado de verdad. Una o dos frases bastan. Lo convierto en tres: planteamiento, remate y callback.","Thank you! You've got one too — write it below.":"¡Gracias a todos! Tú también tienes una, ¿no? Escríbela abajo.","The Bund, Shanghai":"El Bund, Shanghái","The metro":"El metro","The punch is the exact words you said. Don't explain them — stop right after.":"El remate son las palabras exactas que dijiste. No las expliques: para justo después.","Three lines for it · sample":"Tres frases para mi foto · ejemplo","Tianzifang, Shanghai":"Tianzifang, Shanghái","Turn your story into a bit":"Convierte tu anécdota en un monólogo","Two-character given names are the most common. The tones rise and fall, so it sounds good — and every character is easy to read and write.":"Los nombres de pila de dos caracteres son los más comunes. Los tonos suben y bajan, así que suena bien, y cada carácter es fácil de leer y de escribir.","Waiting for a friend":"Esperando a un amigo","Walking with the crowd":"Caminando entre la gente","What makes you feel most like yourself?":"¿Qué te hace sentir más tú?","What were you doing right then?":"¿Qué estabas haciendo en ese momento?","What's your name?":"¿Cómo te llamas?","Why":"Por qué","World Street Snap":"Fotos de calle del mundo","Write one line about you first":"Primero escribe una frase sobre ti","Write your own story above and she'll make it yours.":"Escribe arriba tu propia historia y ella la convertirá en tu monólogo.","Writes one line for a photo — and three for yours.":"Escribe una frase para cada foto, y tres para la tuya.","Xiaoyu":"Xiaoyu","Xiaoyu is writing":"Xiaoyu está escribiendo","Xiaoyu's voice":"La voz de Xiaoyu","YOUR BIT":"TU MONÓLOGO","Your action first, the truth second. The gap between them is the laugh.":"Primero lo que hiciste, luego la verdad. La distancia entre las dos cosas es la risa.","Your birthday":"Tu fecha de nacimiento","Your level":"Tu nivel","Your own story…":"Tu propia historia…","Yu Garden, Shanghai":"Jardín Yu, Shanghái","Zhou Lan":"Zhou Lan","Zhou Lan is looking at your photo":"Zhou Lan está mirando tu foto","Zhujiajiao, Shanghai":"Zhujiajiao, Shanghái","character":"personaje","e.g. ":"p. ej.: ","for a boy":"para un niño","for a girl,":"para una niña,","light":"la luz","long":"versión larga","medium":"versión media","short":"versión corta","source":"fuente","the sea":"el mar","trees":"los árboles","with your own voice":"con tu propia voz","your level":"tu nivel","“Jón's daughter”. The last name is a parent's first name — so the phone book goes by first name.":"«Hija de Jón». El apellido es el nombre de pila de uno de los padres, así que la guía telefónica se ordena por el nombre.","“Light rain” — rain that isn't heavy. Chinese parents choose characters for their meaning, and for how they sound together.":"«Lluvia ligera»: una lluvia que no cae fuerte. Los padres chinos eligen los caracteres por su significado y por cómo suenan juntos.","“Sorrows” — short for María de los Dolores, Our Lady of Sorrows. A sad meaning, a much-loved name.":"«Dolores», de María de los Dolores, la Virgen de los Dolores. Un significado triste, un nombre muy querido.","嘉树, “a fine tree”, comes from Qu Yuan's poem Ode to the Orange Tree (橘颂), over 2,000 years old.":"嘉树, «un árbol hermoso», viene del poema «Oda al naranjo» (橘颂) de Qu Yuan, de hace más de 2000 años.","安澜 is an old word for “the waves have calmed” — peace on the water.":"安澜 es una palabra antigua que significa «las olas se han calmado»: paz sobre el agua.","晴川, “a river in sunshine”, is from the Tang poem Yellow Crane Tower by Cui Hao: 晴川历历汉阳树.":"晴川, «un río bajo el sol», viene del poema Tang «La Torre de la Grulla Amarilla», de Cui Hao: 晴川历历汉阳树.","李 is how Lee is already written in Chinese — one of the most common surnames there is.":"Lee ya se escribe 李 en chino; es uno de los apellidos más comunes que existen.","韦 is an old Chinese surname that sounds like the “We-” of Weber.":"韦 es un apellido chino antiguo que suena como el «We-» de Weber.","马 sounds like the “Ma-” of Martin — and it's one of the common Chinese surnames.":"马 suena como el «Ma-» de Martin, y es uno de los apellidos chinos habituales.","Born on a Sunday:":"Si naciste en domingo:","Born on a Monday:":"Si naciste en lunes:","Born on a Tuesday:":"Si naciste en martes:","Born on a Wednesday:":"Si naciste en miércoles:","Born on a Thursday:":"Si naciste en jueves:","Born on a Friday:":"Si naciste en viernes:","Born on a Saturday:":"Si naciste en sábado:","Ask Xiaoyu to make yours":"Que Xiaoyu te haga uno","Made with Xiaoyu":"Hecho con Xiaoyu","Ask Zhou Lan to make yours":"Que Zhou Lan te haga uno","Made with Zhou Lan":"Hecho con Zhou Lan","Ask Ama to make yours":"Que Ama te haga uno","Made with Ama":"Hecho con Ama"},"ja":{" — like me!":"（わたしと同じ！）","3 LINES":"3つの文","A boy born on a Friday. The girl's Friday name is Afua.":"金曜日に生まれた男の子。金曜日生まれの女の子なら Afua。","A busy lakeside path":"人の多い湖畔の道","A cup of spicy potatoes":"カップ入りの辛いじゃがいも","A girl born on a Saturday. Every Akan child gets a day name.":"土曜日に生まれた女の子。アカンの子どもはみんな、生まれた曜日の名前をもらいます。","A waiter said “enjoy your meal” and I said “you too”.":"店員さんに「enjoy your meal」と言われて、「you too」と返してしまった。","A “virtue name”, like Hope or Faith — English Puritans used them from the 16th century on.":"Hope や Faith のような「美徳の名前」。16世紀からイングランドのピューリタンが使ってきました。","Accra":"アクラ","Accra, Ghana":"ガーナ・アクラ","Add what you were doing — now it's a little story.":"そのとき何をしていたかを足すと、小さな物語になる。","Adventure crew":"探検隊","Akan · Ghana":"アカン語 · ガーナ","Ama":"Ama","Ama is thinking":"Ama が考えています","Among the Akan people of Ghana, the day you were born gives you one of your names. Try it.":"ガーナのアカンの人たちは、生まれた曜日で名前がひとつ決まります。あなたは？","An old Welsh name. The “môr” in it is Welsh for “sea”.":"ウェールズの古い名前。中にある「môr」はウェールズ語で「海」。","Bring the same line back at the end. People laugh twice at a joke they already know.":"最後に同じセリフをもう一度。知っているネタで、人は二度笑う。","Callback":"回収","Chinese · Xiǎoyǔ":"中国語 · Xiǎoyǔ","Choose from your phone":"スマホから選ぶ","Chronicler":"記録係","Close":"閉じる","Coming soon":"近日登場","Couldn't play — tap again":"再生できませんでした。もう一度タップしてください。","Craft":"得意技","Does stand-up — and turns your story into a bit.":"スタンダップをやっていて、あなたの話もネタにしてくれる。","Eating while walking around":"食べ歩き","End with what you do now — count to three. The more exact the habit, the funnier.":"最後は今どうしているかで締める——三つ数える。習慣が具体的なほど面白い。","End with what you do now. A tiny new habit is funnier than a lesson.":"最後は今どうしているかで締める。教訓より、小さな新しい習慣のほうが面白い。","End with what you do now. One small new habit is enough.":"最後は今どうしているかで締める。小さな新しい習慣ひとつで十分。","English":"英語","Everyone has a knack. Tap to bring them along.":"みんなそれぞれ得意なことがある。タップすれば力を貸してくれる。","Example · not your story":"サンプル · あなたの話ではありません","Exchange student. Perfect test scores — then on stage her English goes quiet, so she made that the joke.":"交換留学生。筆記試験は満点なのに、舞台に上がると英語が小声になる。だから、それをネタにした。","First: your own name already works — if people can't say it, teach them. If you want a second one, I'll help.":"まずひとこと。あなたの本名でちゃんと通じます。うまく言ってもらえなければ、教えてあげればいい。二つ目の名前がほしいなら、一緒に選ぶね。","For now this is a ready-made sample and free. Once AI is connected it will use your own words.":"今は用意されたサンプルで、無料です。AI につながったら、あなた自身の言葉を使います。","From Lucia, the feminine of the Roman name Lucius, which comes from the Latin lux, “light”.":"ローマの名前 Lucius の女性形 Lucia から。もとはラテン語の lux（光）。","From the Irish name Ruadhán, “red-haired”. It's also the name of a tree, the rowan.":"アイルランド語の名前 Ruadhán（赤毛の）から。ナナカマドという木の名前でもあります。","Get a Chinese name":"中国語の名前をつけてもらう","Get a line for your photo":"あなたの写真にひとこと","Get an English name":"英語の名前をつけてもらう","Get help with a postcard":"はがきを書くのを手伝ってもらう","Get your self-intro ready":"自己紹介を準備する","Give me a photo you took, and tell me what you were doing right then. I'll write three lines, each a bit longer. You pick one.":"あなたが撮った写真を一枚ちょうだい。そのとき何をしていたかも教えて。少しずつ長くなる三つの文を書くから、ひとつ選んでね。","Guide":"案内人","Hear the whole bit":"ネタを通しで聞く","Helps you name":"名前を考えてくれる","Helps you say":"話すのを手伝ってくれる","Helps you write":"書くのを手伝ってくれる","Her own bit — just listen. Tap any word.":"彼女自身のネタ。聞くだけでOK。単語をタップすると意味が出ます。","Her work":"彼女の作品","I never write about how someone looks. I write about the light, and the moment.":"人の見た目のことは書かない。光と、その瞬間を書くの。","I'll give you a Chinese name: easy to say, easy to write, a real meaning — no strange characters.":"中国語の名前をつけてあげる。言いやすくて、書きやすくて、ちゃんと意味があって、変わった字は使わない。","Icelandic":"アイスランド語","In the real version this line and your voice go out to the world":"正式版では、この一文とあなたの声が世界に届きます","In the real version this line goes out to the world":"正式版では、この一文が世界に届きます","In the real version, this line goes out to the world.":"正式版では、この一文が世界に届きます。","Introduce your name, three ways:":"名前の紹介、三つのレベルで：","It's done. Want to take it out?":"できた。外に出してみる？","Joke writer":"ネタ作家","Keep the setup boring and real. The audience has to stand right where you stood.":"フリは平凡に、本当のことを。客席の人を、あのときのあなたの場所に立たせる。","Knows what names mean — and can give you one.":"名前の意味を知っていて、あなたにもひとつつけてくれる。","Let someone else get the last word. Here your boss's reply is the real ending.":"最後のひとことは他の人に。ここでは上司の返しが本当のオチ。","Let's make it together.":"いっしょに作ろう。","Lines she wrote for Shanghai street photos. The photos are by other photographers; the line is hers.":"上海の街角写真に彼女が添えた一文。写真はほかの写真家のもので、言葉が彼女のもの。","Linguist who studies names":"人名を研究する言語学者","Linguist who studies names — she has also studied how Chinese names are chosen. Twi at home, English for her books, French for West African archives.":"人名を研究する言語学者で、中国語の名前のつけ方も研究してきた。家ではトウィ語、本は英語で書き、西アフリカの資料はフランス語で読む。","Make a share card":"シェア用カードを作る","Make it stand-up · sample":"ネタにして · サンプル","Make the wrong word sound totally normal — said with full confidence.":"言い間違いを、ごく当たり前のように——自信たっぷりに言う。","Make yours first, then it can go out.":"まず自分のを作ってから、外に出せます。","Messenger":"メッセンジャー","NAMED":"名前ができた","Name giver":"名付け親","Name me · sample":"名前をつけて · サンプル","Name the thing and one feeling. That's already a caption.":"何が写っているかと、ひとつの気持ち。それだけでもう一文になる。","Names":"名づけ","Names she has studied. Tap one to turn it over.":"彼女が研究してきた名前。タップすると裏返って意味が出ます。","Nanjing Road at night":"夜の南京路","New York · from Hangzhou":"ニューヨーク · 杭州出身","Not sure? See ones she has done:":"どう書けばいいかわからない？彼女が手を入れた例：","Now you have an Akan day name too.":"これであなたにもアカンの曜日の名前ができました。","Okay, got it.":"うん、覚えた。","On a video call I said “Okay, Mum” to my boss.":"ビデオ会議で上司に「Okay, Mum」と言ってしまった。","One line for a photo":"写真にひとこと","One picture: who and where. The smile matters — it makes your mistake reasonable.":"絵をひとつ：誰が、どこで。笑顔が大事——それがあなたの勘違いを自然にする。","Or write your own…":"または自分で書く……","Photo":"写真","Pick one for now:":"今はこの中から一枚：","Portrait and street photographer":"ポートレート・ストリート写真家","Portrait and street photographer. Asks before she shoots. Never says a word about how anyone looks.":"ポートレートとストリートの写真家。撮る前に必ずひと声かける。人の見た目については何も言わない。","Punch":"オチ","Put everyone in the room. The more people listening, the bigger the punch.":"その場にいた全員を登場させる。聞いている人が多いほど、オチが大きくなる。","Put it on the name wall":"名前の壁に貼る","Riding it for the first time":"初めて乗った","Riding past on a bike":"自転車で通りかかった","Rushing to work":"急いで出勤中","Sample":"サンプル","Sample photo":"サンプル写真","Sample · free":"サンプル · 無料","Sample · the real one sends it":"サンプル · 正式版では送信されます","Sample: pick one below for now":"サンプル：今は下から一枚選んでください","Sample: the real one saves an image with your voice":"サンプル：正式版ではあなたの声つきの画像を保存します","Save image":"画像を保存","Say it — it's yours":"声に出して——あなたの言葉です","Say what you remember, not what you saw. That's the line I'd write.":"見たものじゃなく、覚えていることを書く。わたしならそう書く。","Send to “Two-minute stand-up”":"「2分間スタンダップ」に送る","Send to “World Street Snap”":"「世界ストリートスナップ」に送る","Setup":"フリ","Shanghai":"上海","Someone waved at me, I waved back — they were waving at the person behind me.":"誰かが手を振ってきたので振り返したら、私の後ろの人に振っていた。","Spanish":"スペイン語","Stand-up":"スタンダップコメディ","Take it out":"外に出す","Tell me something embarrassing that really happened to you. One or two sentences. I'll make it three lines: setup, punch, callback.":"あなたに本当にあった恥ずかしい話を教えて。一、二文でいいよ。フリ・オチ・回収の三つにしてあげる。","Thank you! You've got one too — write it below.":"ありがとうございました！あなたにもひとつあるでしょ？下に書いてみて。","The Bund, Shanghai":"外灘（上海）","The metro":"地下鉄の駅","The punch is the exact words you said. Don't explain them — stop right after.":"オチは、そのとき言ったそのままの言葉。説明しないで、言ったらそこで止める。","Three lines for it · sample":"三つの文をつけてもらう · サンプル","Tianzifang, Shanghai":"田子坊（上海）","Turn your story into a bit":"あなたの失敗談をネタにする","Two-character given names are the most common. The tones rise and fall, so it sounds good — and every character is easy to read and write.":"名前は二文字がいちばん多い。声調に上がり下がりがあるので響きがよく、どの字も読みやすく書きやすい。","Waiting for a friend":"友だちを待っていた","Walking with the crowd":"人の流れにのって歩いていた","What makes you feel most like yourself?":"いちばん自分らしいと感じるのは？","What were you doing right then?":"そのとき、何をしていた？","What's your name?":"お名前は？","Why":"なぜ","World Street Snap":"世界ストリートスナップ","Write one line about you first":"まず自分のことを一文書いてね","Write your own story above and she'll make it yours.":"上にあなた自身の話を書くと、彼女があなたのネタにしてくれます。","Writes one line for a photo — and three for yours.":"写真に一文を添える。あなたの写真には三つ。","Xiaoyu":"Xiaoyu","Xiaoyu is writing":"Xiaoyu が書いています","Xiaoyu's voice":"Xiaoyu の声","YOUR BIT":"あなたのネタ","Your action first, the truth second. The gap between them is the laugh.":"先にあなたがしたこと、次に本当のこと。そのズレが笑いになる。","Your birthday":"誕生日","Your level":"あなたのレベル","Your own story…":"あなた自身の話……","Yu Garden, Shanghai":"豫園（上海）","Zhou Lan":"Zhou Lan","Zhou Lan is looking at your photo":"Zhou Lan があなたの写真を見ています","Zhujiajiao, Shanghai":"朱家角（上海）","character":"キャラクター","e.g. ":"例：","for a boy":"は男の子","for a girl,":"は女の子、","light":"光","long":"ロング版","medium":"ミドル版","short":"ショート版","source":"出典","the sea":"海","trees":"木","with your own voice":"あなたの声入り","your level":"あなたのレベル","“Jón's daughter”. The last name is a parent's first name — so the phone book goes by first name.":"「ヨウンの娘」。名字にあたる部分が親の名前なので、電話帳は下の名前で引きます。","“Light rain” — rain that isn't heavy. Chinese parents choose characters for their meaning, and for how they sound together.":"「小雨」——強くない雨。中国の親は、字の意味と、並べたときの響きで名前を選びます。","“Sorrows” — short for María de los Dolores, Our Lady of Sorrows. A sad meaning, a much-loved name.":"「悲しみ」——María de los Dolores（悲しみの聖母）を縮めた名前。悲しい意味なのに、とても愛されている名前。","嘉树, “a fine tree”, comes from Qu Yuan's poem Ode to the Orange Tree (橘颂), over 2,000 years old.":"嘉树（よい木）は、屈原の詩『橘頌』（橘颂）から。2000年以上前の詩です。","安澜 is an old word for “the waves have calmed” — peace on the water.":"安澜 は「波がおさまった」という古いことば。水の上の静けさ。","晴川, “a river in sunshine”, is from the Tang poem Yellow Crane Tower by Cui Hao: 晴川历历汉阳树.":"晴川（日に照らされた川）は、唐の崔顥の詩『黄鶴楼』の一句「晴川历历汉阳树」から。","李 is how Lee is already written in Chinese — one of the most common surnames there is.":"Lee は中国語ではもともと 李 と書きます。いちばん多い名字のひとつです。","韦 is an old Chinese surname that sounds like the “We-” of Weber.":"韦 は古くからある中国の名字で、Weber の「We-」に似た音です。","马 sounds like the “Ma-” of Martin — and it's one of the common Chinese surnames.":"马 は Martin の「Ma-」に似た音で、中国でよくある名字でもあります。","Born on a Sunday:":"日曜日生まれ：","Born on a Monday:":"月曜日生まれ：","Born on a Tuesday:":"火曜日生まれ：","Born on a Wednesday:":"水曜日生まれ：","Born on a Thursday:":"木曜日生まれ：","Born on a Friday:":"金曜日生まれ：","Born on a Saturday:":"土曜日生まれ：","Ask Xiaoyu to make yours":"Xiaoyu に作ってもらう","Made with Xiaoyu":"Xiaoyu と一緒に作った","Ask Zhou Lan to make yours":"Zhou Lan に作ってもらう","Made with Zhou Lan":"Zhou Lan と一緒に作った","Ask Ama to make yours":"Ama に作ってもらう","Made with Ama":"Ama と一緒に作った"},"ar":{" — like me!":" — مثلي!","3 LINES":"3 جمل","A boy born on a Friday. The girl's Friday name is Afua.":"صبي وُلد يوم الجمعة. والبنت المولودة يوم الجمعة اسمها Afua.","A busy lakeside path":"ممشى مزدحم على ضفة البحيرة","A cup of spicy potatoes":"كوب من البطاطا الحارّة","A girl born on a Saturday. Every Akan child gets a day name.":"بنت وُلدت يوم السبت. كل طفل من الأكان يحمل اسمًا بحسب يوم ولادته.","A waiter said “enjoy your meal” and I said “you too”.":"قال لي النادل «enjoy your meal»، فرددت عليه: «you too».","A “virtue name”, like Hope or Faith — English Puritans used them from the 16th century on.":"«اسم فضيلة» مثل Hope أو Faith، استخدمها البيوريتانيون الإنجليز منذ القرن السادس عشر.","Accra":"أكرا","Accra, Ghana":"أكرا، غانا","Add what you were doing — now it's a little story.":"ومع ما كان يحدث معك وقتها، تصير قصة صغيرة.","Adventure crew":"فريق المغامرة","Akan · Ghana":"الأكانية · غانا","Ama":"Ama","Ama is thinking":"Ama تفكّر","Among the Akan people of Ghana, the day you were born gives you one of your names. Try it.":"عند شعب الأكان في غانا، يمنحك يوم ولادتك أحد أسمائك. وأنت؟","An old Welsh name. The “môr” in it is Welsh for “sea”.":"اسم ويلزي قديم، و«môr» فيه تعني «البحر» بالويلزية.","Bring the same line back at the end. People laugh twice at a joke they already know.":"إعادة الجملة نفسها في النهاية. الناس يضحكون مرتين على نكتة يعرفونها.","Callback":"العودة","Chinese · Xiǎoyǔ":"الصينية · Xiǎoyǔ","Choose from your phone":"اختيار من الهاتف","Chronicler":"مؤرّخة اللحظات","Close":"إغلاق","Coming soon":"قريبًا","Couldn't play — tap again":"تعذّر التشغيل. يمكن المحاولة بلمسة أخرى.","Craft":"المهارة","Does stand-up — and turns your story into a bit.":"تقدّم الستاند أب، ويمكنها تحويل قصتك إلى فقرة كوميدية.","Eating while walking around":"كنت آكل وأنا أتمشّى","End with what you do now — count to three. The more exact the habit, the funnier.":"النهاية: عادتك الآن، العدّ إلى ثلاثة. كلما كانت العادة أدقّ، كانت أطرف.","End with what you do now. A tiny new habit is funnier than a lesson.":"النهاية: عادتك الآن. عادة جديدة صغيرة أطرف من أي درس.","End with what you do now. One small new habit is enough.":"النهاية: عادتك الآن. تكفي عادة جديدة صغيرة واحدة.","English":"الإنجليزية","Everyone has a knack. Tap to bring them along.":"لكلٍّ منهم موهبة، وبلمسة واحدة ينضمّ إليك.","Example · not your story":"نموذج · ليست قصتك","Exchange student. Perfect test scores — then on stage her English goes quiet, so she made that the joke.":"طالبة تبادل. علامات كاملة في الامتحانات، لكن على المسرح يخفت صوت إنجليزيتها، فجعلت من ذلك نكتتها.","First: your own name already works — if people can't say it, teach them. If you want a second one, I'll help.":"قبل كل شيء: اسمك الحقيقي يكفي، وإن صعب على الناس نطقه فيمكن تعليمهم إياه. وإن أردت اسمًا ثانيًا، سأساعدك في اختياره.","For now this is a ready-made sample and free. Once AI is connected it will use your own words.":"هذا الآن نموذج جاهز ومجاني. عند ربط الذكاء الاصطناعي سيستخدم كلماتك أنت.","From Lucia, the feminine of the Roman name Lucius, which comes from the Latin lux, “light”.":"من Lucia، المؤنث من الاسم الروماني Lucius، المشتق من اللاتينية lux أي «النور».","From the Irish name Ruadhán, “red-haired”. It's also the name of a tree, the rowan.":"من الاسم الإيرلندي Ruadhán، أي «أحمر الشعر». وهو أيضًا اسم شجرة: الغُبيراء.","Get a Chinese name":"اسم صيني لك","Get a line for your photo":"جملة لصورتك","Get an English name":"اسم إنجليزي لك","Get help with a postcard":"مساعدة في كتابة بطاقة بريدية","Get your self-intro ready":"تحضير تعريف بنفسك","Give me a photo you took, and tell me what you were doing right then. I'll write three lines, each a bit longer. You pick one.":"أحتاج إلى صورة من تصويرك، وإلى جملة عمّا كان يحدث معك في تلك اللحظة. سأكتب ثلاث جمل، كل واحدة أطول قليلًا من السابقة، والاختيار لك.","Guide":"الدليل","Hear the whole bit":"الاستماع إلى الفقرة كاملة","Helps you name":"مساعدة في التسمية","Helps you say":"مساعدة في الكلام","Helps you write":"مساعدة في الكتابة","Her own bit — just listen. Tap any word.":"فقرتها هي، للاستماع فقط. عند لمس أي كلمة يظهر معناها.","Her work":"أعمالها","I never write about how someone looks. I write about the light, and the moment.":"لا أكتب أبدًا عن شكل أحد. أكتب عن الضوء، وعن اللحظة.","I'll give you a Chinese name: easy to say, easy to write, a real meaning — no strange characters.":"سأختار لك اسمًا صينيًا: سهل النطق، سهل الكتابة، له معنى حقيقي، ومن دون حروف غريبة.","Icelandic":"الآيسلندية","In the real version this line and your voice go out to the world":"في النسخة الكاملة تنطلق هذه الجملة وصوتك إلى العالم","In the real version this line goes out to the world":"في النسخة الكاملة تنطلق هذه الجملة إلى العالم","In the real version, this line goes out to the world.":"في النسخة الكاملة تنطلق هذه الجملة إلى العالم.","Introduce your name, three ways:":"تقديم اسمك بثلاث طرق:","It's done. Want to take it out?":"انتهينا. هل نُخرجه إلى العالم؟","Joke writer":"كاتبة كوميديا","Keep the setup boring and real. The audience has to stand right where you stood.":"ليكن التمهيد عاديًا وحقيقيًا. على الجمهور أن يقف حيث وقفتَ أنت.","Knows what names mean — and can give you one.":"تعرف معاني الأسماء، ويمكنها أن تختار لك اسمًا.","Let someone else get the last word. Here your boss's reply is the real ending.":"الكلمة الأخيرة لغيرك. هنا ردّ مديرك هو النهاية الحقيقية.","Let's make it together.":"هيا نصنعه معًا.","Lines she wrote for Shanghai street photos. The photos are by other photographers; the line is hers.":"جمل كتبتها لصور من شوارع شنغهاي. الصور لمصوّرين آخرين، أما الجملة فهي لها.","Linguist who studies names":"لغوية تدرس الأسماء","Linguist who studies names — she has also studied how Chinese names are chosen. Twi at home, English for her books, French for West African archives.":"لغوية تدرس الأسماء، ودرست أيضًا كيف تُختار الأسماء الصينية. تتكلم التوي في البيت، وتكتب كتبها بالإنجليزية، وتقرأ أرشيف غرب أفريقيا بالفرنسية.","Make a share card":"إنشاء بطاقة للمشاركة","Make it stand-up · sample":"حوّليها إلى فقرة كوميدية · نموذج","Make the wrong word sound totally normal — said with full confidence.":"الكلمة الخطأ تُقال كأنها عادية تمامًا، وبثقة كاملة.","Make yours first, then it can go out.":"بعد أن يصبح لديك واحد، يمكن إخراجه إلى العالم.","Messenger":"حامل الرسائل","NAMED":"صار لك اسم","Name giver":"صانعة الأسماء","Name me · sample":"اختاري لي اسمًا · نموذج","Name the thing and one feeling. That's already a caption.":"الشيء وشعور واحد تجاهه: هذا وحده تعليق على الصورة.","Names":"الأسماء","Names she has studied. Tap one to turn it over.":"أسماء درستها. عند لمس أي بطاقة تنقلب ويظهر معناها.","Nanjing Road at night":"شارع نانجينغ ليلًا","New York · from Hangzhou":"نيويورك · من هانغتشو","Not sure? See ones she has done:":"بعض ما صنعته من قبل:","Now you have an Akan day name too.":"صار لديك الآن اسم أكاني أيضًا.","Okay, got it.":"حسنًا، سجّلتُ ذلك.","On a video call I said “Okay, Mum” to my boss.":"في مكالمة فيديو قلت لمديري: «Okay, Mum».","One line for a photo":"جملة لصورة","One picture: who and where. The smile matters — it makes your mistake reasonable.":"صورة واحدة: مَن وأين. الابتسامة مهمة، فهي تجعل خطأك مفهومًا.","Or write your own…":"أو بكلماتك أنت…","Photo":"تصوير","Pick one for now:":"يمكن الآن اختيار واحدة:","Portrait and street photographer":"مصوّرة بورتريه وشارع","Portrait and street photographer. Asks before she shoots. Never says a word about how anyone looks.":"مصوّرة بورتريه وشارع. تستأذن قبل أن تلتقط الصورة، ولا تعلّق أبدًا على شكل أحد.","Punch":"القفلة","Put everyone in the room. The more people listening, the bigger the punch.":"كل الحاضرين في المشهد. كلما كثر المستمعون، قويت القفلة.","Put it on the name wall":"تعليقه على جدار الأسماء","Riding it for the first time":"أول مرة أركبه","Riding past on a bike":"كنت أمرّ بالدراجة","Rushing to work":"كنت في طريقي إلى العمل على عجل","Sample":"نموذج","Sample photo":"صورة نموذجية","Sample · free":"نموذج · مجاني","Sample · the real one sends it":"نموذج · في النسخة الكاملة سيُرسَل","Sample: pick one below for now":"نموذج: يمكن الآن اختيار صورة من الأسفل","Sample: the real one saves an image with your voice":"نموذج: في النسخة الكاملة تُحفظ صورة مع صوتك","Save image":"حفظ الصورة","Say it — it's yours":"حان دورك: هذه كلماتك أنت","Say what you remember, not what you saw. That's the line I'd write.":"ما بقي في الذاكرة، لا ما رأته العين. هكذا كنت سأكتبها أنا.","Send to “Two-minute stand-up”":"إرسال إلى «ستاند أب في دقيقتين»","Send to “World Street Snap”":"إرسال إلى «تصوير الشارع حول العالم»","Setup":"التمهيد","Shanghai":"شنغهاي","Someone waved at me, I waved back — they were waving at the person behind me.":"لوّح لي أحدهم فلوّحت له، وكان يلوّح لمن خلفي.","Spanish":"الإسبانية","Stand-up":"ستاند أب كوميدي","Take it out":"إخراجه إلى العالم","Tell me something embarrassing that really happened to you. One or two sentences. I'll make it three lines: setup, punch, callback.":"أخبرني بموقف محرج حدث لك فعلًا، في جملة أو جملتين. سأحوّله إلى ثلاث: التمهيد، والقفلة، والعودة.","Thank you! You've got one too — write it below.":"شكرًا لكم جميعًا! لديك قصة أيضًا، أليس كذلك؟ يمكنك كتابتها في الأسفل.","The Bund, Shanghai":"البوند، شنغهاي","The metro":"محطة المترو","The punch is the exact words you said. Don't explain them — stop right after.":"القفلة هي الكلمات نفسها التي قلتها. بلا شرح، والتوقف بعدها مباشرة.","Three lines for it · sample":"ثلاث جمل لصورتي · نموذج","Tianzifang, Shanghai":"تيانزيفانغ، شنغهاي","Turn your story into a bit":"تحويل موقفك المحرج إلى فقرة كوميدية","Two-character given names are the most common. The tones rise and fall, so it sounds good — and every character is easy to read and write.":"الأسماء المكوّنة من حرفين صينيين هي الأكثر شيوعًا. النغمات تعلو وتنخفض فيصبح وقعها جميلًا، وكل حرف سهل القراءة والكتابة.","Waiting for a friend":"كنت أنتظر صديقًا","Walking with the crowd":"كنت أمشي مع الزحام","What makes you feel most like yourself?":"ما الذي يشبهك أكثر؟","What were you doing right then?":"ما الذي كان يحدث معك في تلك اللحظة؟","What's your name?":"ما اسمك؟","Why":"لماذا","World Street Snap":"تصوير الشارع حول العالم","Write one line about you first":"أولًا: جملة واحدة عنك","Write your own story above and she'll make it yours.":"عندما تُكتب قصتك أنت في الأعلى، تحوّلها هي إلى فقرتك.","Writes one line for a photo — and three for yours.":"تكتب جملة لكل صورة، وثلاثًا لصورتك.","Xiaoyu":"Xiaoyu","Xiaoyu is writing":"Xiaoyu تكتب","Xiaoyu's voice":"صوت Xiaoyu","YOUR BIT":"فقرتك","Your action first, the truth second. The gap between them is the laugh.":"ما فعلتَه أولًا، ثم الحقيقة. الفجوة بينهما هي الضحكة.","Your birthday":"تاريخ ميلادك","Your level":"مستواك","Your own story…":"قصتك أنت…","Yu Garden, Shanghai":"حديقة يو، شنغهاي","Zhou Lan":"Zhou Lan","Zhou Lan is looking at your photo":"Zhou Lan تنظر إلى صورتك","Zhujiajiao, Shanghai":"تشوجياجياو، شنغهاي","character":"شخصية","e.g. ":"مثلًا: ","for a boy":"للولد","for a girl,":"للبنت،","light":"النور","long":"النسخة الطويلة","medium":"النسخة المتوسطة","short":"النسخة القصيرة","source":"المصدر","the sea":"البحر","trees":"الأشجار","with your own voice":"بصوتك أنت","your level":"مستواك","“Jón's daughter”. The last name is a parent's first name — so the phone book goes by first name.":"«ابنة يون». اسم العائلة هو الاسم الأول لأحد الوالدين، لذلك يُرتَّب دليل الهاتف بالاسم الأول.","“Light rain” — rain that isn't heavy. Chinese parents choose characters for their meaning, and for how they sound together.":"«مطر خفيف»، مطر لا يشتدّ. يختار الآباء الصينيون الحروف لمعناها، ولوقعها معًا.","“Sorrows” — short for María de los Dolores, Our Lady of Sorrows. A sad meaning, a much-loved name.":"«الأحزان»، اختصار لـ María de los Dolores، أي سيدة الأحزان. معنى حزين، واسم محبوب جدًا.","嘉树, “a fine tree”, comes from Qu Yuan's poem Ode to the Orange Tree (橘颂), over 2,000 years old.":"嘉树، أي «شجرة طيبة»، من قصيدة تشيو يوان «نشيد شجرة البرتقال» (橘颂)، وعمرها أكثر من ألفي عام.","安澜 is an old word for “the waves have calmed” — peace on the water.":"安澜 كلمة قديمة تعني «هدأت الأمواج»: سلام على الماء.","晴川, “a river in sunshine”, is from the Tang poem Yellow Crane Tower by Cui Hao: 晴川历历汉阳树.":"晴川، أي «نهر تحت الشمس»، من قصيدة «برج الكركي الأصفر» لتسوي هاو من عهد تانغ: 晴川历历汉阳树.","李 is how Lee is already written in Chinese — one of the most common surnames there is.":"Lee يُكتب بالصينية أصلًا 李، وهو من أكثر أسماء العائلة شيوعًا.","韦 is an old Chinese surname that sounds like the “We-” of Weber.":"韦 اسم عائلة صيني قديم، يشبه صوته «We-» في Weber.","马 sounds like the “Ma-” of Martin — and it's one of the common Chinese surnames.":"马 يشبه صوته «Ma-» في Martin، وهو من أسماء العائلة الصينية الشائعة.","Born on a Sunday:":"إن كانت الولادة يوم الأحد:","Born on a Monday:":"إن كانت الولادة يوم الاثنين:","Born on a Tuesday:":"إن كانت الولادة يوم الثلاثاء:","Born on a Wednesday:":"إن كانت الولادة يوم الأربعاء:","Born on a Thursday:":"إن كانت الولادة يوم الخميس:","Born on a Friday:":"إن كانت الولادة يوم الجمعة:","Born on a Saturday:":"إن كانت الولادة يوم السبت:","Ask Xiaoyu to make yours":"Xiaoyu تصنع لك واحدًا","Made with Xiaoyu":"صُنع مع Xiaoyu","Ask Zhou Lan to make yours":"Zhou Lan تصنع لك واحدًا","Made with Zhou Lan":"صُنع مع Zhou Lan","Ask Ama to make yours":"Ama تصنع لك واحدًا","Made with Ama":"صُنع مع Ama"}}};
