const av = (id, cls) => FACE(id) ? `<img class="cw-av ${cls || ""}" src="${FACE(id)}" alt="">` : `<span class="cw-av cw-sil ${cls || ""}">${SIL}</span>`;
const NM = id => u(PE[id].nm);
const lv = () => { try { return AK().level ? AK().level() : 1; } catch(e){ return 1; } };
const LVN = i => { const L = AK().LEVELS || [["刚开始", "Just starting"], ["能聊日常", "Everyday chat"], ["比较流利", "Fairly fluent"]]; return T(L[i][0], L[i][1]); };
const say = (t, l) => { try { AK().say ? AK().say(t, {l: l || TG()}) : 0; } catch(e){} };
