  pb: a => { const c = S.sheet; c.B = +a.dataset.i; c.rec = null; blip(820); say(tok(COMP(c.cat).mid.B[c.B][0])[0]); renderSheet(); if (lineNow(c)) toSec("jt-s-say"); },
  peek: () => { S.sheet.peek = true; blip(600); renderSheet(); },
  useex: () => { const c = S.sheet; c.useEx = true; c.free = ""; c.rec = null; blip(1000); say(pl(L(COMP(c.cat).ex))); renderSheet(); toSec("jt-s-say"); },
  hearme: a => { const r = S.sheet && S.sheet.rec; if (r && r.blob) playBlob(r.blob, a); },
  mood: a => { const c = S.sheet; c.mood = a.dataset.m; const m = MOOD(c.mood); blip(1200); say(moodW(m)[0]); renderSheet(); },
  priv: a => { S.sheet.world = a.dataset.w === "1"; blip(S.sheet.world ? 1200 : 700); renderSheet(); },
  keep: async () => { const c = S.sheet, x = c && lineNow(c); if (!x || !c.rec) return; const tl = c.ti != null && TITLES(c.cat) ? TITLES(c.cat)[c.ti] : null;
    const e = {id: "j" + Date.now().toString(36), d: today(), ts: Date.now(), cat: c.cat, ti: c.ti, wk: tl && tl[3] ? tl[3] : null, tt: tl ? tl[0] : null, ph: c.ph, lg: SIDE(), l: x, mood: c.mood || null, w: 0, lv: c.lv};
    if (e.ph === "l" && c.phB){ await put("ph", e.id, c.phB); PHU[e.id] = c.phU; }
    if (c.rec.blob) await put("rec", e.id, {blob: c.rec.blob, dur: c.rec.dur, heard: c.rec.heard, t: c.rec.t});
    const o = ST(); o.e.unshift(e); SAVE(o);
    const RR = ((D().REPLY || {})[SIDE()] || {})[c.cat] || {}, Dc = COMP(c.cat);
    const ri = c.useEx || c.lv === 2 ? null : c.lv === 1 ? (RR.mid || [])[c.B] : (RR.beg || [])[Dc.beg.o.findIndex(o2 => c.built.includes(o2[0]))];
    const rl = L(ri || RR.any), world = c.world, rec = c.rec;
    S.sheet = null; S.newId = e.id; S.filter = "all"; S.banner = null; stopAu(); render(); PG.querySelector(".jt-jr").scrollTo({top: 0, behavior: "smooth"});
    setTimeout(() => { stamp(T("记", "Jotted"), dLabel(e.d)); if (!world) confetti(18); }, 250);
    if (world){ const id = await sendWorld(e, rec); if (id){ setTimeout(() => { stamp("SENT", T("送给世界", "TO THE WORLD")); confetti(46); }, 1800); upd(e.id, x2 => { x2.w = 1; x2.wid = id; }); S.banner = {id: e.id, wk: wkOf(e), cat: e.cat}; render(); } }
    clearTimeout(KT); KT = setTimeout(() => { if (PG && !PG.hidden && !S.sheet && RR.who && rl) buddy(RR.who, rl); }, 1900);
    setTimeout(() => { S.newId = null; PG && PG.querySelectorAll(".jt-grow,.jt-pop").forEach(y => y.classList.remove("jt-grow", "jt-pop")); }, 1800); },
