/* ───── 页 ───── */
function mount(){ try { A().mount(); } catch(e){}
  if (!document.getElementById("jtCss")){ const s = document.createElement("style"); s.id = "jtCss"; s.textContent = CSS; document.head.appendChild(s); }
  if (PG) return;
  PG = document.createElement("div"); PG.id = "jotPg"; PG.className = "jt-pg"; PG.hidden = true; PG.dataset.nopy = "";
  PG.innerHTML = `<div class="jt-jr"></div><button class="jt-fab" data-jt="new"></button><div class="jt-sdim" data-jt="sclose"></div><div class="jt-sheet"></div><div class="jt-det"></div><div class="jt-buddy"></div><div class="jt-flash"></div>`;
  document.body.appendChild(PG);
  PG.addEventListener("click", e => { const sp = e.target.closest(".jt-sp"); if (sp){ e.stopPropagation(); say(sp.dataset.jsay, sp.dataset.jl); blip(990); return; }
    const a = e.target.closest("[data-jt]"); if (a && PG.contains(a)){ const f = ACT[a.dataset.jt]; if (NOTE8.includes(a.dataset.jt)) note8(a); if (f) f(a, e); } });
  PG.addEventListener("error", e => { const t = e.target; if (t && t.tagName === "IMG" && t.classList.contains("jt-av")){ t.style.visibility = "hidden"; } }, true);
  document.addEventListener("keydown", e => { if (e.key === "Escape" && PG && !PG.hidden){ if (S.det) ACT.dclose(); else if (S.sheet) ACT.sclose(); else close(); } }); }
function open(o){ o = o || {}; if (!A() || !D().CATS || !LGOK()) return; mount(); lnClose(); S.det = null; S.sheet = null; S.banner = null;
  PG.hidden = false; document.body.classList.add("jt-on"); void PG.offsetWidth; PG.classList.add("on"); render();
  if (o.jot) ACT.new();
  try { window.hvPulse && window.hvPulse("jot"); } catch(e){} }
function close(){ if (!PG) return; stopAu(); clearTimeout(KT); PG.classList.remove("on"); document.body.classList.remove("jt-on"); S.sheet = null; S.det = null;
  setTimeout(() => { if (!PG.classList.contains("on")) PG.hidden = true; }, 380); }

/* ───── 下拉的小程序（手机）+ 左边一栏的按钮（电脑）───── */
const PHONE = () => innerWidth <= 700;
// 只在四个主页面（今天 · 世界 · 人 · 我）：地址是这四个之一，手指摸到的（或屏幕上方那一块）属于这四页本身；盖在上面的页（活动页这类）不出来
const MAINR = ["boat", "today", "map", "people", "me"], MAINP = "#boatPg,#wnPg,#ppPg,#mlPg";
const mainOn = el => { const g = document.getElementById("galTabs"); if (!g || (PG && !PG.hidden)) return false; const cs = getComputedStyle(g); if (cs.display === "none" || cs.visibility === "hidden") return false;
  let r = ""; try { r = window.hvRt.now(); } catch(e){} if (!MAINR.includes(r)) return false;
  const pts = el ? [el] : [150, 300, innerHeight / 2].map(y => document.elementFromPoint(innerWidth / 2, Math.min(y, innerHeight - 90)));
  return pts.some(t => t && t.closest && t.closest(MAINP)); };
const RECENT = () => ls("jot.lnch") || [];
function APPS(){ const zh = ZH(), list = LGOK() ? [{id: "jot", ic: "✍️", nm: T("记一笔", "Jot it"), sub: zh ? "记一笔" : "", go: () => open()}] : [];
  if (!LGOK()) return list;
  if (zh && window.ZHT){ list.push({id: "cam", ic: "📷", nm: T("拍照识字", "Snap & read"), go: () => ZHT.camera()}); list.push({id: "py", ic: "🔤", nm: T("拼音表", "Pinyin"), go: () => ZHT.pinyin()}); }
  if (!zh && window.ENT){ list.push({id: "cam", ic: "📷", nm: T("拍照认词", "Read a sign"), go: () => ENT.camera()}); list.push({id: "snd", ic: "🔤", nm: T("英文发音", "Sounds"), go: () => ENT.sounds()}); }
  return list; }
function lnRender(){ const L2 = APPS(), rec = RECENT().map(id => L2.find(a => a.id === id)).filter(Boolean).slice(0, 4);
  const one = a => `<button class="jt-app${a.id === "jot" ? " jot" : ""}" data-lnapp="${esc(a.id)}"><span class="ic">${a.ic}</span>${esc(a.nm)}${a.sub ? `<small>${esc(a.sub)}</small>` : ""}</button>`;
  LN.querySelector(".jt-pan").innerHTML = (rec.length ? `<div class="jt-lrow">${esc(T("最近用的", "Recent"))}</div><div class="jt-apps">${rec.map(one).join("")}</div>` : "") + `<div class="jt-lrow">${esc(T("全部", "All"))}</div><div class="jt-apps">${L2.map(one).join("")}</div><span class="jt-pull"></span>`; }
function lnOpen(){ if (!A()) return; mount(); if (!LN){ LN = document.createElement("div"); LN.id = "jotLaunch"; LN.className = "jt-launch"; LN.innerHTML = `<div class="jt-ldim"></div><div class="jt-pan"></div>`; document.body.appendChild(LN);
    LN.addEventListener("click", e => { const b = e.target.closest("[data-lnapp]"); if (b){ const a = APPS().find(x => x.id === b.dataset.lnapp); if (!a) return; blip(900); const r = RECENT().filter(x => x !== a.id); r.unshift(a.id); ls("jot.lnch", r.slice(0, 6)); lnClose(); setTimeout(() => a.go(), 120); return; } if (e.target.closest(".jt-ldim")) lnClose(); });
    let y0 = null; LN.addEventListener("touchstart", e => { y0 = e.touches[0].clientY; }, {passive: true}); LN.addEventListener("touchend", e => { if (y0 != null && y0 - e.changedTouches[0].clientY > 50) lnClose(); y0 = null; }); }
  lnRender(); LN.hidden = false; void LN.offsetWidth; LN.classList.add("on"); blip(660); }
function lnClose(){ if (!LN || LN.hidden) return; LN.classList.remove("on"); setTimeout(() => { if (!LN.classList.contains("on")) LN.hidden = true; }, 360); }
function railBtn(){ const g = document.getElementById("galTabs"); if (!g) return; const old = g.querySelector(".jt-rail"); if (!LGOK()){ if (old) old.remove(); return; } if (old) return; mount(); const b = document.createElement("button"); b.className = "jt-rail"; b.type = "button";
  b.innerHTML = `<b>✍️</b>${esc(T("记一笔", "Jot it"))}`; b.setAttribute("aria-label", T("记一笔", "Jot it")); b.addEventListener("click", e => { e.stopPropagation(); if (PG && !PG.hidden) close(); else open(); }); g.appendChild(b); }
function handle(){ if (!HD){ mount(); HD = document.createElement("button"); HD.className = "jt-handle"; HD.type = "button"; HD.setAttribute("aria-label", T("小程序", "Mini-apps")); HD.addEventListener("click", lnOpen); document.body.appendChild(HD);
    if (!ls("jot.lnch")) HD.classList.add("hint"); }
  HD.hidden = !(LGOK() && PHONE() && mainOn() && !document.body.classList.contains("ak-on")); }
// 拇指往下拉：页面已经在最上面（摸到的那一层和整页都没往下滚）再往下拉 80px，就出来一排小程序
let PY = null, PX = 0;
const atTop = el => { for (let n = el; n && n !== document.documentElement; n = n.parentElement){ if (n.scrollTop > 0) return false; } return (window.scrollY || 0) <= 0; };
document.addEventListener("touchstart", e => { PY = null; if (!PHONE() || !A() || !LGOK() || e.touches.length !== 1 || (LN && !LN.hidden) || !mainOn(e.target)) return; if (e.target.closest && e.target.closest("input,textarea,select,.leaflet-container,svg,canvas,#galTabs")) return; if (!atTop(e.target)) return; PY = e.touches[0].clientY; PX = e.touches[0].clientX; }, {passive: true, capture: true});
document.addEventListener("touchmove", e => { if (PY == null) return; const t = e.touches[0], dy = t.clientY - PY, dx = Math.abs(t.clientX - PX); if (dx > 40 && dx > dy){ PY = null; return; } if (dy > 80 && dy > dx * 2){ PY = null; lnOpen(); } }, {passive: true, capture: true});
document.addEventListener("touchend", () => { PY = null; }, {passive: true, capture: true});
setInterval(() => { if (!A() || !D().CATS) return; railBtn(); handle(); }, 1000);

window.JOT = {open, close, launcher: lnOpen, isOpen: () => !!PG && !PG.hidden, entries: all};

